def facing(sm):
    md = sm.get_static_mesh_description(0); n = md.get_vertex_count(); st = max(1, n // 2500)
    pts = [md.get_vertex_position(unreal.VertexID(i)) for i in range(0, n, st)]
    xs = [p.x for p in pts]; ys = [p.y for p in pts]; zs = [p.z for p in pts]
    x0, x1, y0, y1, z0, z1 = min(xs), max(xs), min(ys), max(ys), min(zs), max(zs)
    cx, cy = (x0 + x1) / 2, (y0 + y1) / 2; dx, dy = x1 - x0, y1 - y0
    ax = 'x' if dx < dy else 'y'
    hi = [p for p in pts if p.z > z0 + 0.62 * (z1 - z0) and (abs(p.y - cy) < 0.3 * dy if ax == 'x' else abs(p.x - cx) < 0.3 * dx)] or [p for p in pts if p.z > z0 + 0.62 * (z1 - z0)]
    off = (sum(p.x for p in hi) / len(hi) - cx) / dx if ax == 'x' else (sum(p.y for p in hi) / len(hi) - cy) / dy
    return '%s%+.2f %d,%d,%d c%d,%d,%d' % (ax, off, dx, dy, z1 - z0, cx, cy, z0)
out = []
for k, p in sorted(P.items()):
    sm = unreal.load_asset(p) if p else None
    try: out.append('%s:%s' % (k[3:] if k.startswith('SM_') else k, facing(sm) if sm else 'X'))
    except Exception as e: out.append(k + ':ERR')
for i in range(0, len(out), 6): print('F', ' | '.join(out[i:i + 6]))
